const baseUrl = $env.QBIT_URL;
const username = $env.QBIT_USERNAME;
const password = $env.QBIT_PASSWORD;
const staleThresholdSeconds = 24 * 60 * 60;
const formHeaders = { 'Content-Type': 'application/x-www-form-urlencoded' };
const toForm = (obj) => Object.entries(obj).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');

const loginRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `${baseUrl}/api/v2/auth/login`,
  headers: formHeaders,
  body: toForm({ username, password }),
  returnFullResponse: true,
});

const setCookie = loginRes.headers['set-cookie'];
if (!setCookie) {
  throw new Error('qBittorrent login failed - no cookie returned');
}
const cookie = Array.isArray(setCookie) ? setCookie[0].split(';')[0] : setCookie.split(';')[0];

const torrents = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/v2/torrents/info`,
  headers: { Cookie: cookie },
  json: true,
});

const now = Math.floor(Date.now() / 1000);
const stuck = torrents.filter((t) =>
  t.state === 'error' ||
  t.state === 'missingFiles' ||
  (t.state === 'stalledDL' && now - t.added_on > staleThresholdSeconds)
);

if (stuck.length > 0) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/api/v2/torrents/delete`,
    headers: { ...formHeaders, Cookie: cookie },
    body: toForm({
      hashes: stuck.map((t) => t.hash).join('|'),
      deleteFiles: 'true',
    }),
  });
}

return [{
  json: {
    service: 'qBittorrent',
    deletedCount: stuck.length,
    deletedNames: stuck.map((t) => t.name),
  },
  pairedItem: { item: 0 },
}];

const baseUrl = $env.SABNZBD_URL;
const apikey = $env.SABNZBD_APIKEY;

const history = await this.helpers.httpRequest({
  method: 'GET',
  url: baseUrl,
  qs: { mode: 'history', failed_only: 1, output: 'json', apikey },
  json: true,
});

const failed = (history.history && history.history.slots) || [];

if (failed.length > 0) {
  await this.helpers.httpRequest({
    method: 'GET',
    url: baseUrl,
    qs: {
      mode: 'history',
      name: 'delete',
      value: failed.map((j) => j.nzo_id).join(','),
      del_files: 1,
      output: 'json',
      apikey,
    },
  });
}

return [{
  json: {
    service: 'SABnzbd',
    deletedCount: failed.length,
    deletedNames: failed.map((j) => j.name),
  },
  pairedItem: { item: 0 },
}];

const items = $input.all();
const lines = [];
let total = 0;

for (const item of items) {
  const { service, deletedCount, deletedNames } = item.json;
  total += deletedCount;
  if (deletedCount > 0) {
    lines.push(`${service}: removed ${deletedCount} (${deletedNames.join(', ')})`);
  }
}

return [{
  json: {
    total,
    message: lines.join('\n') || 'No stuck or failed downloads found.',
  },
  pairedItem: { item: 0 },
}];
